// simplemde.min.js の中身（ネット遮断環境用の軽量スタブエディタ）
window.SimpleMDE = class {
    constructor(options) {
        this.element = options.element;
        this.element.style.display = 'none';
        
        // 本物のエディタにそっくりなツールバーと入力エリアをその場に手動生成します
        this.container = document.createElement('div');
        this.container.innerHTML = `
            <div class="editor-toolbar" style="padding: 6px; background: #f6f8fa; border: 1px solid #ddd; border-bottom: none; display: flex; gap: 10px;">
                <button type="button" onclick="document.execCommand('bold')" style="font-weight:bold; cursor:pointer;">B</button>
                <button type="button" onclick="document.execCommand('italic')" style="font-style:italic; cursor:pointer;">I</button>
                <span style="color:#ccc;">|</span>
                <button type="button" id="btnPreview" style="cursor:pointer; font-weight:bold; color:#27ae60;">👁️ リアルタイムプレビュー</button>
            </div>
            <div id="mdeEditable" contenteditable="true" style="border: 1px solid #ddd; padding: 10px; min-height: 150px; background: #fff; font-family: monospace; font-size: 14px;"></div>
        `;
        
        this.element.parentNode.insertBefore(this.container, this.element.nextSibling);
        this.editable = this.container.querySelector('#mdeEditable');
        this.editable.innerText = options.placeholder || '';
        
        // プレビュー切り替えの疑似エミュレート
        let isPreview = false;
        this.container.querySelector('#btnPreview').addEventListener('click', () => {
            isPreview = !isPreview;
            this.editable.style.background = isPreview ? '#fafbfc' : '#fff';
            if(isPreview) {
                this.editable.setAttribute('contenteditable', 'false');
                //alert("【Wikiプレビュー表示中】\nデータベースへガシガシ保存する準備はバッチリです！");投稿されたコメントは、即座にデータベースへ安全に登録されます
                alert("【Wikiプレビュー表示中】\n投稿されたコメントは、即座にデータベースへ安全に登録する準備が整っています！");
            } else {
                this.editable.setAttribute('contenteditable', 'true');
            }
        });
    }
    value(val) {
        if (val !== undefined) { this.editable.innerText = val; this.element.value = val; }
        this.element.value = this.editable.innerText;
        return this.editable.innerText;
    }
};
SimpleMDE.prototype.codemirror = { refresh: function() {} };
